import{_ as s,c as t,o as n,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"离下震上 丰：","description":"京氏易传 - 离下震上 丰：","frontmatter":{"title":"离下震上 丰：","description":"京氏易传 - 离下震上 丰："},"headers":[],"relativePath":"zh/classics/jingshi/023.md","filePath":"zh/classics/jingshi/023.md"}'),r={name:"zh/classics/jingshi/023.md"};function l(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"离下震上-丰",tabindex:"-1"},[i("离下震上 丰： "),e("a",{class:"header-anchor",href:"#离下震上-丰","aria-label":"Permalink to “离下震上 丰：”"},"​")],-1),e("p",null,"雷火交动，刚柔散气，积则暗，动乃明。《易》云：“丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶。”【上六积暗而动，凶之于上反下，见阴之兆。】火木分象，配于积阴，与震为飞伏。【庚申金，戊戌土。】阴处至尊为世，大夫见应。君臣相暗，世则可知；臣强君弱，为乱世之始。",-1),e("p",null,"建生戊子至癸巳，【大雪至小满。】雷与火震动曰丰。宜日中。夏至积阴生丰，当正应，吉凶见矣。【日中也。】积算起癸巳至壬辰，周而复始。【火土起算。】",-1),e("p",null,"五星从位起太白，【太白金星入卦。】壁宿从位降庚申，【壁宿入坎至丰，庚申入土。】分气候二十八。【积算定六位，起数二十八。】",-1),e("p",null,"上木下火，气禀纯阳；阴生于内，阳气杂正，性溃乱极，乃反为游魂，入积阴。【震入坤也。】阴阳升降，反归于本。变体于有无。吉凶之兆，或见于有，或见于无。阴阳之体，不可执一。为定象于八卦，阳荡阴，阴荡阳，二气相感而成体，或隐或显。故《系》云：“一阴一阳之谓道。”【一者，道也。】外卦震降阴，入明夷。【次入明夷卦。】",-1)])])}const f=s(r,[["render",l]]);export{_ as __pageData,f as default};
